def evalPostfix(tokens):
    stack = []
    for t in tokens:
        if 100001 <= t <= 100004:
            b = stack.pop()
            a = stack.pop()
            if t == 100001:
                stack.append(a + b)
            elif t == 100002:
                stack.append(a - b)
            elif t == 100003:
                stack.append(a * b)
            else:
                q = abs(a) // abs(b)
                stack.append(q if (a < 0) == (b < 0) else -q)
        else:
            stack.append(t)
    return stack[0]
